import{_ as r,o as t,c as o,aj as a}from"./chunks/framework.C6uXqnaX.js";const c=JSON.parse('{"title":"What is Angular?","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),n={name:"overview.md"};function s(i,e,l,u,g,d){return t(),o("div",null,e[0]||(e[0]=[a('<h1 id="what-is-angular" tabindex="-1">What is Angular? <a class="header-anchor" href="#what-is-angular" aria-label="Permalink to &quot;What is Angular?&quot;">​</a></h1><p>Angular is a web framework that empowers<br> developers to build fast, reliable applications that users love.</p><div style="margin:2em;"> Maintained by a dedicated team at Google, Angular provides a broad suite of tools, APIs, and libraries to simplify and streamline your development workflow. Angular gives you a solid platform on which to build fast, reliable applications that scale with both the size of your team and the size of your codebase. Angular.dev is the official home for Angular documentation. </div><p><strong>Want to see some code?</strong></p><ul><li><a href="/essentials"><strong>Essentials</strong></a>: An overview of what it&#39;s like to use Angular</li><li><a href="/tutorials"><strong>Tutorials</strong></a>: Step-by-step instructions in your browser</li></ul><p><strong>Features that power your development</strong></p><ul><li><a href="/essentials/components"><strong>Components</strong></a>: Angular components make it easy to split your code into well-encapsulated parts.</li><li><a href="/essentials/signals"><strong>Angular Signals</strong></a>: Our fine-grained reactivity model, combined with compile-time optimizations, simplifies development and helps build faster apps by default.</li><li><a href="/guide/ssr"><strong>Server-side rendering</strong></a>: Angular supports both server-side rendering (SSR) and static site generation (SSG) along with full DOM hydration.</li><li><a href="/essentials/dependency-injection"><strong>Dependency injection</strong></a>: Easily share code across components throughout your entire application.</li><li><a href="/guide/routing"><strong>Angular Routing</strong></a>: Provides a feature-rich navigation toolkit, including support for route guards, data resolution, lazy-loading, and much more.</li><li><a href="/guide/forms"><strong>Forms in Angular</strong></a>: Provides a standardized system for form participation and validation.</li></ul><p><strong>Develop applications faster than ever</strong></p><ul><li><a href="/tools/cli"><strong>CLI</strong></a>: Angular CLI gets your project running in under a minute with the commands you need to grow into a deployed production application.</li><li><a href="/tools/devtools"><strong>DevTools</strong></a>: Angular DevTools sits alongside your browser&#39;s developer tools. It helps debug and analyze your app, including a component tree inspector, dependency injection tree view, and custom performance profiling flame chart.</li><li><a href="/update"><strong>ng update</strong></a>: Angular CLI&#39;s <code>ng update</code> runs automated code transformations that automatically handle routine breaking changes, dramatically simplifying major version updates. Keeping up with the latest version keeps your app as fast and secure as possible.</li><li><a href="/tools/language-service"><strong>Language Service</strong></a>: Angular&#39;s IDE language service powers code completion, navigation, refactoring, and real-time diagnostics in your favorite editor.</li></ul><p><strong>Ship with confidence</strong></p><ul><li><a href="https://cacm.acm.org/research/why-google-stores-billions-of-lines-of-code-in-a-single-repository/" target="_blank" rel="noreferrer"><strong>Verified commit-by-commit against Google&#39;s colossal monorepo</strong></a>: <p>Every Angular commit is checked against hundreds of thousands of tests in Google&#39;s internal code repository, representing countless real-world scenarios.</p> <p>Angular is committed to stability for some of Google’s largest products, including Google Cloud. This commitment ensures changes are well-tested, backwards compatible, and include migration tools whenever possible.</p></li><li><a href="/reference/releases"><strong>Clear support policies and predictable release schedule</strong></a>: Angular&#39;s predictable, time-based release schedule gives your organization confidence in the stability and backwards compatibility of the framework. Long Term Support (LTS) windows make sure you get critical security fixes when you need them. First-party update tools, guides and automated migration schematics help keep your apps up-to-date with the latest advancements to the framework and the web platform.</li></ul><p><strong>Works at any scale</strong></p><ul><li><a href="/guide/i18n"><strong>Reach users everywhere with internationalization support</strong></a>: Angular&#39;s internationalization features handle message translations and formatting, including support for unicode standard ICU syntax.</li><li><a href="/best-practices/security"><strong>Protect your users with security by default</strong></a>: In collaboration with Google&#39;s world-class security engineers, Angular aims to make development safe by default. Built-in security features, including HTML sanitization and trusted type support, help protect your users from common vulnerabilities like cross-site scripting and cross-site request forgery.</li><li><a href="/tools/cli/build-system-migration"><strong>Keep large teams productive with Vite and esbuild</strong></a>: Angular CLI includes a fast, modern build pipeline using Vite and esbuild. Developers report building projects with hundreds of thousands of lines of code in less than a minute.</li><li><strong>Proven in some of Google&#39;s largest web apps</strong>: Large Google products build on top of Angular&#39;s architecture and help develop new features that further improve Angular&#39;s scalability, from <a href="https://fonts.google.com/" target="_blank" rel="noreferrer">Google Fonts</a> to <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">Google Cloud</a>.</li></ul><p><strong>Open-source first</strong></p><ul><li><a href="https://github.com/angular/angular" target="_blank" rel="noreferrer"><strong>Made in the open on GitHub</strong></a>: Curious what we’re working on? Every PR and commit is available on our GitHub. Run into an issue or bug? We triage GitHub issues regularly to ensure we’re responsive and engaged with our community, and solving the real world problems you’re facing.</li><li><a href="/roadmap"><strong>Built with transparency</strong></a>: Our team publishes a public roadmap of our current and future work and values your feedback. We publish Request for Comments (RFCs) to collect feedback on larger feature changes and ensure the community voice is heard while shaping the future direction of Angular.</li></ul><p><strong>A thriving community</strong></p><ul><li><a href="https://devlibrary.withgoogle.com/products/angular?sort=added" target="_blank" rel="noreferrer"><strong>Courses, blogs and resources</strong></a>: Our community is composed of talented developers, writers, instructors, podcasters, and more. The Google for Developers library is just a sample of the high quality resources available for new and experienced developers to continue developing.</li><li><a href="https://github.com/angular/angular/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><strong>Open Source</strong></a>: We are thankful for the open source contributors who make Angular a better framework for everyone. From fixing a typo in the docs, to adding major features, we encourage anyone interested to get started on our GitHub.</li><li><a href="https://developers.google.com/community/experts/directory?specialization=angular" target="_blank" rel="noreferrer"><strong>Community partnerships</strong></a>: Our team partners with individuals, educators, and enterprises to ensure we consistently are supporting developers. Angular Google Developer Experts (GDEs) represent community leaders around the world educating, organizing, and developing with Angular. Enterprise partnerships help ensure that Angular scales well for technology industry leaders.</li><li><strong>Partnering with other Google technologies</strong>: <p>Angular partners closely with other Google technologies and teams to improve the web.</p> <p>Our ongoing partnership with Chrome’s Aurora actively explores improvements to user experience across the web, developing built-in performance optimizations like <code>NgOptimizedImage</code> and improvements to Angular’s Core Web Vitals.</p> <p>We are also working with <a href="https://firebase.google.com/" target="_blank">Firebase</a>, <a href="https://www.tensorflow.org/" target="_blank">TensorFlow</a>, <a href="https://flutter.dev/" target="_blank">Flutter</a>, <a href="https://m3.material.io/" target="_blank">Material Design</a>, and <a href="https://cloud.google.com/" target="_blank">Google Cloud</a> to ensure we provide meaningful integrations across the developer workflow.</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Join the momentum!</p><ul><li><a href="/roadmap">Read Angular&#39;s roadmap</a></li><li><a href="https://angular.dev/playground" target="_blank" rel="noreferrer">Try out our playground</a></li><li><a href="/tutorials">Learn with tutorials</a></li><li><a href="https://youtube.com/playlist?list=PL1w1q3fL4pmj9k1FrJ3Pe91EPub2_h4jF" target="_blank" rel="noreferrer">Watch our YouTube course</a></li><li><a href="/api">Reference our APIs</a></li></ul></div>',18)]))}const h=r(n,[["render",s]]);export{c as __pageData,h as default};
